public static INDArray pad(INDArray toPad, int[][] padWidth, List<double[]> constantValues, PadMode padMode) {
  switch (padMode) {
    case CONSTANT:    if (padWidth.length < toPad.rank())     throw new IllegalArgumentException("Please specify a pad width for each dimension");
      List<int[]> sizes = new ArrayList<>();
      for (int i = 0; i < toPad.rank(); i++) {
        try {
          sizes.add(padWidth[i]);
        } catch (IndexOutOfBoundsException e) {
          throw new IllegalArgumentException("padWidth or constantValues list is not correctly sized for the rank of the array", e);
        }
      }
      INDArray ret = toPad;
      for (int i = 0; i < toPad.rank(); i++) {
        int[] pad = sizes.get(i);
        double[] constant = constantValues.get(i);
        int padBefore = pad[0];
        int padAfter = pad[1];
        if (constant.length < 2) {
          double val = constant[0];
          constant = new double[2];
          constant[0] = val;
          constant[1] = val;
        }
        double beforeVal = constant[0];
        double afterVal = constant[1];
        try {
          ret = Nd4j.prepend(ret, padBefore, beforeVal, i);
          ret = Nd4j.append(ret, padAfter, afterVal, i);
        } catch (IndexOutOfBoundsException e) {
          throw new IllegalArgumentException("padWidth or constantValues list is not correctly sized for the rank of the array", e);
        }
      }
      return ret;
    default: throw new UnsupportedOperationException();
  }
}
